"""Centers and parallel axes for bounded and unbounded figures, XIV, p. 328."""
import argparse
import json
from rotated_circles_lines import diagram
from translations_and_rotations import lesson
from vector_scaling import BOOK,ROOT

OUT=ROOT/'geometry-course/textbook/data/bounded-symmetries.json'


def triangle(title,a,b):
    return diagram(title,{'A':(0,0),'B':(a,0),'C':(0,b)},[('A','B'),('B','C'),('C','A')])


def no_symmetry():
    return lesson(1274,None,328,'Придумай многоугольник без внутренних симметрий. Как доказать, что ни одно нетождественное движение ему не подходит?',
      'Выберем прямоугольный треугольник со сторонами 3, 4 и 5. При движении каждая сторона обязана перейти в сторону той же длины. Поскольку длины попарно различны, каждая сторона переходит в себя. Пересечения сторон, то есть все три вершины, остаются на месте. Движение, оставляющее три не лежащие на одной прямой точки неподвижными, тождественно: расстояния до трёх таких точек однозначно определяют всякую точку. Поэтому внутренних симметрий нет. Та же причина подходит для любого разностороннего треугольника.',
      [('Сопоставь стороны по длине','В первом треугольнике AB=4, AC=3, BC=5. У каждой стороны только один возможный образ.','Если совпала длина только одной стороны, этого ещё недостаточно. Проверь каждую из трёх.'),
       ('Определи образ вершины','На втором чертеже катеты равны 5 и 12. Найди длину третьей стороны. Самая длинная сторона переходит в себя, а её концы различимы по другим сторонам.','Отражение в перпендикуляре к гипотенузе поменяло бы концы с разными прилежащими катетами.'),
       ('Проверь другой треугольник','Третий треугольник с катетами 6 и 8 снова разносторонний. Его вершины закреплены пересечениями сторон. Посчитай только внутренние симметрии.','Тождественное движение существует всегда, но по принятому в этой главе определению в ответ не входит.')],
      [triangle('Стороны 3, 4 и 5',4,3),triangle('Катеты 5 и 12',12,5),triangle('Другие длины 6 и 8',8,6)],
      [('Какова длина гипотенузы у второго треугольника?','13','Квадрат гипотенузы равен 25+144.'),('Сколько внутренних симметрий у третьего треугольника?','0','Все три стороны и все три вершины закреплены.')],
      'Движение обязано сохранять все попарные расстояния. Три неподвижные неколлинеарные точки определяют его однозначно.',
      'Подбери такую фигуру, в которой каждую вершину можно отличить от всех других по длинам сторон.',
      'AB и AC — катеты. Сравни все три длины.','Приведи собственный пример и исключи все нетождественные движения.',refs=[123,127])


def quad(title,h,u,v):
    pts={k:(h[0]+x,h[1]+y) for k,(x,y) in zip('ABCD',[u,v,(-u[0],-u[1]),(-v[0],-v[1])],strict=True)}
    return diagram(title,{**pts,'T':h},[('A','B'),('B','C'),('C','D'),('D','A')],[(pts['A'],pts['C']),(pts['B'],pts['D'])])


def center_quad():
    return lesson(1275,None,328,'У четырёхугольника есть центр симметрии T. Обоснуй, почему четырёхугольник обязательно является параллелограммом.',
      'Полуоборот вокруг T переводит вершины четырёхугольника в вершины и сохраняет направление обхода границы. Никакая вершина не может оставаться неподвижной: тогда она совпала бы с T, а три другие должны были бы разбиться на пары, что невозможно. Полуоборот переставляет четыре вершины сдвигом на два места в порядке обхода: сдвиг на одно или три места дважды подряд не вернул бы их назад. Значит, A и C меняются местами, как и B и D. Центр T — середина обеих диагоналей. По признаку параллелограмма получаем требуемое.',
      [('Проследи за границей','Обход A,B,C,D после поворота идёт в том же направлении. После двух полуоборотов каждая вершина должна вернуться на место.','Если бы A перешла в соседнюю B, сохраняя порядок обхода, то B перешла бы в C, и два полуоборота перевели бы A в C.'),
       ('Соедини пары вершин','Во втором примере AC горизонтальна, AT=4. Точка C — образ A при полуобороте. Найди полную длину AC.','Длина от вершины до центра составляет половину диагонали, а не всю её длину.'),
       ('Примени признак','В третьей схеме T делит AC и BD пополам, а BT=3. Найди BD и объясни, почему двух общих середин достаточно для параллелограмма.','Равенство длин разных диагоналей здесь вообще не требуется: равны две части каждой из них.')],
      [quad('Циклический порядок четырёх вершин',(0,0),(3,1),(-1,2)),quad('Середина горизонтальной диагонали',(1,0),(4,0),(1,2)),quad('Середина вертикальной диагонали',(1,1),(4,1),(0,3))],
      [('Чему равна AC, если AT=4?','8','T — середина AC.'),('Чему равна BD, если BT=3?','6','Обе части BD имеют длину 3.')],
      'Полуоборот переводит каждую точку в точку по другую сторону от центра на таком же расстоянии.',
      'Сначала установи, какие вершины меняются местами, затем вспомни признак параллелограмма по диагоналям.',
      'T — общий центр. Выделены диагонали AC и BD.','Обоснуй парность противоположных вершин и сделай вывод о четырёхугольнике.',refs=[124,127])


def line_frame(title,h,x,gap=0):
    # The UI clips unbounded lines. No artificial ends are listed as figure vertices.
    pts={'A':(x-2,h+gap),'T':(x,h),'A′':(x+2,h-gap)}
    marks=[((-5,h),(5,h))] if not gap else [((-5,h-gap),(5,h-gap)),((-5,h+gap),(5,h+gap)),((-5,h),(5,h))]
    return diagram(title,pts,[('A','A′')] if gap else [],marks)


def many_centers():
    return lesson(1276,None,328,'Построй примеры фигур с бесконечным множеством центров симметрии. Где именно находятся их центры?',
      'У бесконечной прямой любая её точка T является центром: для A на прямой отложим TA по прямой в другую сторону. Получим A′ на той же прямой, причём обратное построение возвращает A. Другой пример — полоса между двумя параллельными прямыми вместе с её границами. Любая точка средней прямой полосы служит центром: полуоборот обменивает границы, а точки между ними остаются между образами границ. Центр вне средней прямой не подойдёт: расстояния до границ различны, поэтому полуоборот не сможет обменять их.',
      [('Выбери точку на прямой','Возьми произвольную точку T на бесконечной прямой. Образ любой точки A той же прямой опять лежит на ней. Сдвинь T: аргумент сохраняется.','Нарисованные концы видимой линии — края рисунка. Прямая продолжается бесконечно.'),
       ('Проверь расстояния до границ','На втором рисунке ширина полосы 4, а T лежит на средней прямой. Найди расстояние от него до каждой границы.','Центр полосы не обязан стоять в середине видимого окна: его можно смещать вдоль средней прямой.'),
       ('Измени полосу и положение центра','В третьем примере ширина равна 6. Центр T сдвинут вдоль полосы. Проверь, сохраняются ли расстояния до двух границ.','Полуоборот переводит обе границы друг в друга. Если расстояния до них разные, этого не произойдёт.')],
      [line_frame('Прямая продолжается в обе стороны',0,0),line_frame('Полоса ширины 4',1,0,2),line_frame('Новая полоса ширины 6',0,1,3)],
      [('Чему равно расстояние от T до границы полосы ширины 4?','2','Средняя прямая делит ширину пополам.'),('Чему равно расстояние от T до границы полосы ширины 6?','3','Положение вдоль средней прямой не влияет на расстояние.')],
      'Полуоборот сохраняет расстояния и меняет местами точки, серединой между которыми является выбранный центр.',
      'Проверь прямую, затем бесконечную полосу. В каждом примере перемещай центр по целой прямой.',
      'Горизонтальные линии продолжаются за рамку. T — один из центров, A′ — образ A.',
      'Назови две разные фигуры и укажи, почему у каждой бесконечно много центров.',refs=[123,126,127])


def chain(title,d,x,parallel):
    pts={'A':(x,1),'B':(-x,1 if parallel else -1),'C':(2*d+x,1),'T':(0,0),'S':(d,0)}
    marks=[((0,-2),(0,2)),((d,-2),(d,2))] if parallel else []
    return diagram(title,pts,[('A','B'),('B','C')],marks)


def impossible(parallel):
    z='1278' if parallel else '1277'
    cases=[chain(t,d,-1,parallel) for t,d in zip(['Два последовательных преобразования','Измерь результирующий сдвиг','Повтори на новом расстоянии'],[2,3,4],strict=True)]
    if parallel:
        task='Могут ли две различные параллельные прямые быть осями симметрии многоугольника? Обоснуй ответ.'
        proof='Пусть первая ось задаётся уравнением x=0, вторая x=d, где d>0, а координата y направлена вдоль осей. Два последовательных отражения переводят (x,y) сначала в (−x,y), затем в (2d+x,y). Их композиция — перенос на 2d поперёк осей. Если бы оба отражения сохраняли многоугольник, перенос тоже сохранял бы его. Но вершина с наибольшей абсциссой не может перейти в вершину с ещё большей абсциссой. Значит, двух различных параллельных осей у многоугольника быть не может.'
        steps=[('Отрази дважды','На первой схеме оси вертикальны. A отражается относительно оси через T в B, затем B относительно оси через S в C. У точек A и C одинаковые ординаты.','Два отражения в разных параллельных прямых не возвращают начало: у второго отражения другая ось.'),
               ('Удвой расстояние между осями','На второй схеме расстояние между прямыми равно 3. Установи, насколько правее A находится C.','Расстояние между осями — только половина длины результирующего переноса.'),
               ('Найди крайнюю вершину','В третьем примере расстояние между осями стало 4. Посчитай сдвиг и примени его к самой правой вершине многоугольника.','Окно на рисунке ограничено, но аргумент опирается на ограниченность самого многоугольника.') ]
        rule='Композиция двух отражений в разных параллельных прямых есть перенос в перпендикулярном направлении на удвоенное расстояние между ними.'
        caption='T и S лежат на двух вертикальных осях. Сначала отражаем A в B, затем B в C.'
    else:
        task='Может ли у одного многоугольника быть ровно два различных центра симметрии? Объясни, что произойдёт при двух последовательных полуоборотах.'
        proof='Допустим, что T и S — разные центры. Возьмём ось x вдоль TS, обозначим через d>0 расстояние TS и выберем начало координат в T. Полуоборот вокруг T переводит (x,y) в (−x,−y). Следующий полуоборот вокруг S=(d,0) даёт (2d+x,y). Вместе они сдвигают каждую точку вправо на 2d. Если каждое из движений сохраняет многоугольник, этот сдвиг тоже переставляет его вершины. У самой правой вершины нет образа ещё правее в том же многоугольнике. Противоречие: у многоугольника может быть не более одного центра.'
        steps=[('Выполни полуобороты по порядку','На первом рисунке T — середина AB, S — середина BC. Вектор AC направлен так же, как TS, но длиннее в два раза.','Второй полуоборот выполняется вокруг S, а не вокруг T.'),
               ('Посчитай расстояние между A и C','Во второй схеме TS=3. Координата вдоль TS после первого полуоборота меняет знак, после второго к исходной прибавляется удвоенное TS.','Длина результирующего сдвига не зависит от выбора A.'),
               ('Примени к самой правой вершине','В третьей схеме TS=4. Найди длину переноса и представь такой сдвиг для вершины с наибольшей абсциссой.','У прямой центров бесконечно много, но здесь рассуждение опирается на существование крайней вершины именно у многоугольника.')]
        rule='Два полуоборота вокруг разных точек в сумме дают перенос на удвоенный вектор от первого центра ко второму.'
        caption='T — центр первого полуоборота, S — второго. A переходит в B, затем в C.'
    return lesson(int(z),None,328,task,proof,steps,cases,
      [('Чему равна длина AC при TS=3?','6','Получившийся перенос имеет длину 2·3.'),('Чему равна длина AC при TS=4?','8','Второе движение завершает сдвиг на 2·4.')],
      rule,'Найди результат двух движений для одной точки. Примени его к вершине многоугольника, крайней в направлении сдвига.',
      caption,'Докажи свой ответ, вычислив композицию и выбрав крайнюю вершину.',refs=[124,125,126,127])


if __name__=='__main__':
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    rows=[no_symmetry(),center_quad(),many_centers(),impossible(False),impossible(True)]
    raw=json.dumps({'bookId':BOOK,'lessons':rows},ensure_ascii=False,separators=(',',':'))+'\n'
    if parser.parse_args().check:assert OUT.read_text()==raw
    else:OUT.write_text(raw)
